import 'factual_dimensions.dart';

/// Dimensión concreta y su familia factual I, M o E.
final class FactualQuestionDimension {
  const FactualQuestionDimension(this.code, this.instruction, this.familyCode);
  final String code;
  final String instruction;
  final String familyCode;

  FactualDimension get family => factualDimensions.firstWhere(
    (item) => item.code == familyCode,
  );
  FactualDimensionGroup get group => family.group;
}

